def _component_06(data):
    packages = data["packages"]
    names = sorted(packages, reverse=True)
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    roots = data["roots"]
    choices = []
    for name in names:
        rows = [row for row in packages[name]
                if row["version"] not in blocked.get(name, [])
                and (name not in pins or row["version"] == pins[name])]
        choices.append([None] + rows)

    best = None
    best_vector = None
    for combo in product(*choices):
        selected = {name: row for name, row in zip(names, combo) if row is not None}
        if any(name not in selected or not low <= selected[name]["version"] <= high
               for name, (low, high) in roots.items()):
            continue
        graph = {}
        valid = True
        for name, row in selected.items():
            deps = []
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                other = dep["name"]
                if (other not in selected or
                        not dep["min"] <= selected[other]["version"] <= dep["max"]):
                    valid = False
                    break
                deps.append(other)
            graph[name] = deps
            if not valid:
                break
        if not valid:
            continue

        reachable = set()
        stack = list(roots)
        while stack:
            name = stack.pop()
            if name in reachable:
                continue
            if name not in selected:
                valid = False
                break
            reachable.add(name)
            stack.extend(graph[name])
        if not valid or reachable != set(selected):
            continue

        done, active = set(), set()
        def visit(name):
            if name in active:
                return False
            if name in done:
                return True
            active.add(name)
            if any(not visit(dep) for dep in graph[name]):
                return False
            active.remove(name)
            done.add(name)
            return True
        if not all(visit(name) for name in graph):
            continue

        vector = tuple(selected[name]["version"] if name in selected else -1
                       for name in names)
        if best_vector is None or vector < best_vector:
            best_vector = vector
            best = {name: row["version"] for name, row in selected.items()}
    return {"versions": best} if best is not None else {"error": "unsatisfiable"}


def _component_07(data):
    jobs = data["jobs"]
    k = data["k"]
    blocked = set(data.get("blocked", []))
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    options = [job for job in jobs if job["id"] not in blocked]
    best_ids, best_value = None, None
    n = len(options)
    for mask in range(1 << n):
        if mask.bit_count() != k:
            continue
        chosen = [options[i] for i in range(n) if mask >> i & 1]
        ids = {job["id"] for job in chosen}
        if not mandatory <= ids:
            continue
        counts = {}
        for job in chosen:
            counts[job["group"]] = counts.get(job["group"], 0) + 1
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue
        ordered = sorted(chosen, key=lambda job: (job["start"], job["end"]))
        if any(ordered[i]["start"] < ordered[i - 1]["end"]
               for i in range(1, len(ordered))):
            continue
        value = sum(job["value"] for job in chosen)
        id_list = tuple(sorted(ids))
        if (best_value is None or value > best_value or
                (value == best_value and id_list > best_ids)):
            best_value, best_ids = value, id_list
    if best_value is None:
        return {"error": "impossible"}
    return {"selected": list(best_ids), "value": best_value}


def _component_08(data):
    required = data.get("required", [])
    bit = {node: 1 << i for i, node in enumerate(required)}
    full = (1 << len(required)) - 1
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)
    source = data["source"]
    initial_mask = bit.get(source, 0)
    start = data["start"]
    initial = (source, 0, initial_mask)
    dist = {initial: start}
    queue = [(start, source, 0, initial_mask)]
    while queue:
        time, node, used, mask = heapq.heappop(queue)
        state = (node, used, mask)
        if dist.get(state) != time:
            continue
        if node == data["target"] and used == data["coupons"] and mask == full:
            return {"arrival": time}
        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            for spend in (0, 1):
                if used + spend > data["coupons"]:
                    continue
                duration = edge["duration"]
                if spend:
                    duration = max(1, duration - edge.get("discount", 0))
                arrival = depart + duration
                if arrival > data["deadline"]:
                    continue
                dest = edge["v"]
                next_mask = mask | bit.get(dest, 0)
                next_state = (dest, used + spend, next_mask)
                if arrival < dist.get(next_state, float("inf")):
                    dist[next_state] = arrival
                    heapq.heappush(queue, (arrival, dest, used + spend, next_mask))
    return {"arrival": None}


